const MONEY_EPSILON = 0.01;

function isGhostWork(work = {}) {
  return Boolean(work?.isGhost) || (typeof work?.userId === 'string' && work.userId.startsWith('ghost-'));
}

function getWorkUnits(work = {}) {
  if (work.type === 'full-day') return 1;
  if (work.type === 'half-day') return 0.5;
  if (work.type === 'variable' && work.timerMode !== 'overtime') {
    const hours = Math.max(0, Number(work.variableHours ?? work.durationHours) || 0);
    return hours / 8;
  }
  return 0;
}

/**
 * Calculates the amount generated by one work entry using the member's rates.
 */
export function getWorkEarnings(work, dailyRate = 0, extraHourRate = 0) {
  if (isGhostWork(work)) return 0;
  const regularAmount = getWorkUnits(work) * (Number(dailyRate) || 0);
  const overtimeAmount = Math.max(0, Number(work?.overtimeHours) || 0) * (Number(extraHourRate) || 0);
  return regularAmount + overtimeAmount;
}

/**
 * Returns the member's outstanding balance for the whole team history.
 *
 * Period filters are deliberately not applied here: a debt remains payable even
 * when the work that generated it belongs to an earlier month.
 */
export function getOutstandingAmount(works = [], payments = [], dailyRate = 0, extraHourRate = 0) {
  const totalEarned = works.reduce(
    (sum, work) => sum + getWorkEarnings(work, dailyRate, extraHourRate),
    0,
  );
  const totalPaid = payments.reduce(
    (sum, payment) => sum + Math.max(0, Number(payment?.amount) || 0),
    0,
  );
  const outstanding = Math.max(totalEarned - totalPaid, 0);
  return outstanding <= MONEY_EPSILON ? 0 : outstanding;
}
